struct vector3d { float x, y, z; };
class sector;

class partition3 {
  char padding[0x10];
  sector* my_sector;
public:
  sector* get_sector() const { return my_sector; }
};

class tree_t {
public:
  struct node { node* left; node* parent; node* right; partition3 value; };
  class iterator {
    node* ptr;
  public:
    iterator() {}
    iterator(node* p) : ptr(p) {}
    partition3* operator->() const { return &ptr->value; }
    node* _Mynode() const { return ptr; }
  };
  class branch {
  public:
    enum dir_t { RIGHT, LEFT, NONE };
    iterator parent;
    dir_t child;
  };

  branch find_leaf(const vector3d& key) const;
  sector* find_sector(const vector3d& pos) const;
};

sector* tree_t::find_sector(const vector3d& pos) const
{
  branch br = find_leaf(pos);
  if (br.child == branch::LEFT)
    return 0;
  return br.parent->get_sector();
}
